<?php defined('ALTUMCODE') || die(); if(!\Altum\Authentication::is_admin())return; $heartbeat=fcc_partner_notification_config('heartbeat');$phone_heartbeat=fcc_partner_notification_config('heartbeat_phone');$devices=(int)(fcc_partner_one('SELECT COUNT(*) n FROM fcc_partner_push_subscriptions WHERE active=1')['n']??0);$rules=fcc_partner_notification_config('rules',array_fill_keys(array_keys(fcc_partner_notification_rules()),true)); ?>
<section class="fp-panel"><div class="fp-section-title fp-wrap-heading"><h2><?= htmlspecialchars(fcc_t('Automatske obavijesti'), ENT_QUOTES, 'UTF-8') ?></h2><a href="<?= url('partner/notifications') ?>"><?= htmlspecialchars(fcc_t('Moj inbox →'), ENT_QUOTES, 'UTF-8') ?></a></div>
<p><?= htmlspecialchars(fcc_t('Postojeće FCC poruke, uključujući prvu PRO aktivaciju i rezultate klikova, ulaze u isti inbox. Pravila ispod upravljaju dodatnim push slanjem; ne mijenjaju postojeće e-mail automatizacije.'), ENT_QUOTES, 'UTF-8') ?></p>
<p class="fp-message"><?= $heartbeat?fcc_t('Posljednja obrada: ').$h((new \DateTimeImmutable($heartbeat['at']))->setTimezone(new \DateTimeZone('Europe/Zagreb'))->format('d.m.Y. H:i').fcc_t(' Zagreb')).fcc_t(' · računa: ').(int)$heartbeat['accounts']:fcc_t('Obrada još nije pokrenuta.') ?> · <?= $h(fcc_partner_push_mode_label(fcc_partner_push_mode())) ?></p>
<p><?= htmlspecialchars(fcc_t('Aktivnih prijava uređaja:'), ENT_QUOTES, 'UTF-8') ?> <strong><?= $devices ?></strong><?= htmlspecialchars(fcc_t('. Status „Prihvatio push servis” potvrđuje predaju servisu; primitak i otvaranje na telefonu provjeravaju se zasebno.'), ENT_QUOTES, 'UTF-8') ?></p>
<?php if(getenv('FCC_LOCAL')==='1'&&$phone_heartbeat): ?><p class="fp-muted"><?= htmlspecialchars(fcc_t('HTTPS test · posljednja obrada:'), ENT_QUOTES, 'UTF-8') ?> <?= $h((new \DateTimeImmutable($phone_heartbeat['at']))->setTimezone(new \DateTimeZone('Europe/Zagreb'))->format('d.m.Y. H:i')) ?> <?= htmlspecialchars(fcc_t('Zagreb ·'), ENT_QUOTES, 'UTF-8') ?> <?= $h(fcc_partner_push_mode_label($phone_heartbeat['transport'])) ?><?= time()-strtotime($phone_heartbeat['at'])>300?fcc_t(' · Obrada kasni dulje od 5 minuta.'):'' ?></p><?php endif ?>
<p class="fp-muted"><?php if(getenv('FCC_LOCAL')==='1'): ?><?= htmlspecialchars(fcc_t('Postojeća naplata i e-mail automatizacije lokalno se provjeravaju testovima, bez stvarnog slanja. Ovo nije status produkcijskog rasporeda.'), ENT_QUOTES, 'UTF-8') ?><?php else: ?><?= htmlspecialchars(fcc_t('Izvorni FCC cron:'), ENT_QUOTES, 'UTF-8') ?> <?= $h(settings()->cron->cron_datetime??fcc_t('Nema zabilježene obrade u ovom okruženju')) ?><?= htmlspecialchars(fcc_t('. Slanje postojećih e-mailova i obrada 15+/50+ ostaju u tom procesu.'), ENT_QUOTES, 'UTF-8') ?><?php endif ?></p>
<details><summary><?= htmlspecialchars(fcc_t('Vrste poruka i uključivanje push slanja'), ENT_QUOTES, 'UTF-8') ?></summary><form method="post" class="fp-form"><?= $token ?><input type="hidden" name="action" value="notification_rules"><?php foreach(fcc_partner_notification_rules() as $key=>[$title,$desc]): ?><label class="fp-check-label"><input type="checkbox" name="rules[]" value="<?= $key ?>" <?= !empty($rules[$key])?'checked':'' ?>><span><?= $h($title) ?><small><?= $h($desc) ?></small></span></label><?php endforeach ?><button class="fp-button"><?= htmlspecialchars(fcc_t('Spremi pravila'), ENT_QUOTES, 'UTF-8') ?></button></form></details>
<div class="fp-filter-row"><?php foreach(fcc_partner_rows('SELECT status,COUNT(*) n FROM fcc_partner_push_deliveries GROUP BY status') as $count): ?><span><?= $h(['pending'=>fcc_t('Čeka slanje'),'sent'=>fcc_t('Prihvatio push servis'),'simulated'=>'Simulirano','failed'=>'Neuspjelo','skipped'=>fcc_t('Preskočeno'),'sending'=>fcc_t('U obradi')][$count['status']]??$count['status']) ?>: <strong><?= (int)$count['n'] ?></strong></span><?php endforeach ?></div>
<details><summary><?= htmlspecialchars(fcc_t('Posljednje isporuke i razlozi'), ENT_QUOTES, 'UTF-8') ?></summary><?php foreach(fcc_partner_rows('SELECT d.status,d.last_code,d.updated_at,n.title FROM fcc_partner_push_deliveries d JOIN fcc_partner_notifications n ON n.id=d.notification_id ORDER BY d.id DESC LIMIT 15') as $delivery): ?><p class="fp-muted"><?= $h($delivery['title'].' · '.$delivery['status'].' · '.($delivery['last_code']??'').' · '.$delivery['updated_at'].fcc_t(' UTC')) ?></p><?php endforeach ?></details>
